/**
 * The shader runtime of the effects layer (ADR 0022, 0025) — OPTIONAL. Install
 * it only for `gradient` (the parametric ground) and `halo`; every CSS effect
 * works without it.
 *
 *   // once, in a client component at the app root (or a <script> in Astro)
 *   useEffect(() => startShaders(), []);
 *
 *   <section className={fx("gradient")} style={{ "--ui-fx-gradient-look": "rise" }}>…</section>
 *
 * It finds every element carrying a shader effect's class, mounts one canvas
 * in the part the effect paints, and draws it from tokens read where that
 * part sits. When it cannot draw — no WebGL2, a lost context, before it has
 * started, on the server — the component is untouched: THE FLOOR IS THE
 * COMPONENT, and it was already finished.
 *
 * Three objects, one job each:
 *   Renderer   the one WebGL2 context for the page (browsers allow about 16),
 *              its programs, and context loss
 *   Target     one canvas in one part: geometry, token reads, paint
 *   Scheduler  discovery, observers, the frame loop, states, quality
 *
 * The page sees each target's state on the effect's root as
 * `data-fx-<name>`: `live` · `still` (reduced motion, or a frozen clock) ·
 * `floor` (not drawing) · `lost` (context lost) · `unsupported` (no WebGL2).
 * shader.css shows a canvas only when it is `live` or `still`.
 *
 * Found on an iPhone, not in headless Chromium, and the reason for two
 * choices below: iOS Safari drops a CSS border-radius clip on a canvas while
 * its layer animates, so the SHADER draws the part's rounded shape; and a
 * positioned child starts at the padding box, so the canvas steps back over
 * the border to cover the border box.
 */

import { SHADERS, VERTEX, PRELUDE, type ShaderDef, type ShaderName, type UniformValues } from "@/lib/shader-programs";

type Values = UniformValues;

export type ShaderState = "floor" | "live" | "still" | "lost" | "unsupported";

export interface ShaderSettings {
  /** null follows the OS setting; true/false forces it (stories, tests). */
  reducedMotion: boolean | null;
  /** Every target shows its floor, as without WebGL. For tests and stories. */
  forceFloor: boolean;
  /** A number freezes every clock at that time: deterministic frames. */
  freezeAt: number | null;
  /** Device-pixel cap. 2 is indistinguishable from 3 at these feature sizes. */
  maxDpr: number;
  /** null adapts to frame time; a number pins the quality step (tests). */
  quality: number | null;
}

/**
 * Where a shader effect draws, per component — keyed by the ROOT's
 * `data-slot`, with `*` for any other element (a ground).
 *
 * - `part`   the rounded box the shader draws. Default: the root.
 * - `mount`  where the canvas lives; it covers this element's border box.
 *            Default: the part. A Slider's or a Progress's FILL is drawn on
 *            a canvas in the TRACK, so a growing fill reveals a still field
 *            and its rounded end is drawn by the shader, not clipped by CSS.
 *            `"root"` mounts a halo where its part's own overflow cannot cut it.
 * - `layer`  `under` (default): above the mount's background, below its
 *            content — a label, a check glyph. `over`: above a sibling fill
 *            inside a track, inserted DIRECTLY AFTER the fill so every later
 *            sibling (the origin mark, the THUMB) still paints above it.
 *            Appended last, it covered the Slider's thumb.
 *
 * A part that does not exist leaves the root at its floor.
 */
export interface ShaderRecipe {
  part?: string;
  mount?: string;
  layer?: "under" | "over";
}

export const SHADER_RECIPES: Record<ShaderName, Record<string, ShaderRecipe>> = {
  gradient: {
    "*": {},
  },
  halo: {
    button: {},
    field: { part: '[data-slot="control"]', mount: "root" },
    "*": {},
  },
};

const NAMES = Object.keys(SHADERS) as ShaderName[];
const SELECTOR = NAMES.map((n) => `.fx-${n}`).join(", ");

export const settings: ShaderSettings = { reducedMotion: null, forceFloor: false, freezeAt: null, maxDpr: 2, quality: null };

// --- reading tokens ----------------------------------------------------------

let swatch: CanvasRenderingContext2D | null = null;

/**
 * A colour token resolved where `el` sits — its brand scope, its scheme — as
 * sRGB 0..1. The browser resolves light-dark(), color-mix() and oklch(); a
 * 1×1 canvas reads the result back, which is the one parser that agrees with
 * the browser on every colour syntax by construction.
 */
export function readColor(el: HTMLElement, token: string, fallbackToken?: string): [number, number, number] {
  if (!swatch) {
    const c = document.createElement("canvas");
    c.width = c.height = 1;
    swatch = c.getContext("2d", { willReadFrequently: true });
  }
  const prev = el.style.color;
  // A fallback token, not a declared default: a default declared on the
  // effect's own class would override what a wrapper or a brand scope sets.
  el.style.color = fallbackToken ? `var(${token}, var(${fallbackToken}))` : `var(${token})`;
  const css = getComputedStyle(el).color;
  el.style.color = prev;
  if (!swatch) return [0, 0, 0];
  swatch.clearRect(0, 0, 1, 1);
  swatch.fillStyle = "#000";
  swatch.fillStyle = css;
  swatch.fillRect(0, 0, 1, 1);
  const d = swatch.getImageData(0, 0, 1, 1).data;
  return [d[0]! / 255, d[1]! / 255, d[2]! / 255];
}

/** Each unreadable token value is said once, not every frame. */
const warned = new Set<string>();
function warnOnce(token: string, raw: string, expected: string) {
  const key = `${token}:${raw}`;
  if (warned.has(key)) return;
  warned.add(key);
  console.warn(`[shader] ${token}: "${raw}" is not ${expected}; using the default.`);
}

/**
 * A keyword token: the index of its value in `values`, or 0 (the first) when
 * unset. Quotes and case are forgiven (`"Rise"` is `rise`); an unknown value
 * is said once and reads as the first.
 */
export function readKeyword(el: Element, token: string, values: readonly string[]): number {
  const raw = getComputedStyle(el).getPropertyValue(token).trim();
  const word = raw.replace(/^["']|["']$/g, "").toLowerCase();
  const i = values.indexOf(word);
  if (i < 0 && word && word !== "auto") warnOnce(token, raw, `one of ${values.join(", ")}`);
  return Math.max(0, i);
}

/**
 * A numeric token, in the unit the program expects: `2000ms` → 2 (seconds),
 * `16px` → 16, `24deg` → 24, `0.1turn` → 36 (degrees), `1rad` → 57.3, `50%`
 * → 0.5, `0.6` → 0.6. Unset or `auto` → the fallback, silently. Anything
 * else — `calc()`, an unknown unit — is said once and reads as the fallback:
 * a custom property's value is not evaluated, so `calc(…)` arrives as text.
 */
export function readNumber(el: Element, token: string, fallback: number): number {
  const raw = getComputedStyle(el).getPropertyValue(token).trim();
  if (!raw || raw === "auto") return fallback;
  const m = raw.match(/^([-+]?(?:\d+\.?\d*|\.\d+)(?:e[-+]?\d+)?)([a-z%]*)$/i);
  const n = m ? parseFloat(m[1]!) : NaN;
  const unit = m?.[2]?.toLowerCase() ?? "";
  const scale: Record<string, number> = { "": 1, px: 1, deg: 1, s: 1, ms: 1 / 1000, "%": 1 / 100, turn: 360, rad: 180 / Math.PI, grad: 0.9 };
  if (!Number.isFinite(n) || !(unit in scale)) {
    warnOnce(token, raw, "a number");
    return fallback;
  }
  return n * scale[unit]!;
}

// --- Renderer ------------------------------------------------------------------

interface Program {
  program: WebGLProgram;
  loc: Map<string, WebGLUniformLocation | null>;
}

class Renderer {
  readonly canvas = document.createElement("canvas");
  gl: WebGL2RenderingContext | null = null;
  lost = false;
  private programs = new Map<ShaderName, Program | null>();

  constructor(private readonly onRestored: () => void) {}

  /** True when drawing is possible right now. */
  init(): boolean {
    if (this.gl) return !this.lost;
    const gl = this.canvas.getContext("webgl2", {
      alpha: true,
      premultipliedAlpha: true,
      antialias: false,
      depth: false,
      stencil: false,
      powerPreference: "low-power",
    });
    if (!gl) return false;
    this.gl = gl;
    this.canvas.addEventListener("webglcontextlost", (e) => {
      e.preventDefault();
      this.lost = true;
      this.programs.clear();
    });
    this.canvas.addEventListener("webglcontextrestored", () => {
      this.lost = false;
      this.onRestored();
    });
    return true;
  }

  private program(def: ShaderDef): Program | null {
    const cached = this.programs.get(def.name);
    if (cached !== undefined) return cached;
    const gl = this.gl!;
    const compile = (type: number, src: string) => {
      const s = gl.createShader(type)!;
      gl.shaderSource(s, src);
      gl.compileShader(s);
      if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s) ?? "compile failed");
      return s;
    };
    let result: Program | null = null;
    try {
      const program = gl.createProgram()!;
      gl.attachShader(program, compile(gl.VERTEX_SHADER, VERTEX));
      gl.attachShader(program, compile(gl.FRAGMENT_SHADER, PRELUDE + def.fragment));
      gl.linkProgram(program);
      if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program) ?? "link failed");
      result = { program, loc: new Map() };
    } catch (err) {
      // A program that does not compile on this GPU leaves its targets at the
      // floor. Said once, not every frame.
      console.error(`[shader] ${def.name}:`, (err as Error).message);
    }
    this.programs.set(def.name, result);
    return result;
  }

  /** Draw one target's frame into the bottom-left w×h of the shared canvas. */
  draw(def: ShaderDef, w: number, h: number, uniforms: Values): boolean {
    const gl = this.gl;
    if (!gl || this.lost) return false;
    const p = this.program(def);
    if (!p) return false;
    // Grows only, in 128px steps: resizing a canvas reallocates its buffer.
    const W = Math.max(this.canvas.width, Math.ceil(w / 128) * 128);
    const H = Math.max(this.canvas.height, Math.ceil(h / 128) * 128);
    if (W !== this.canvas.width || H !== this.canvas.height) {
      this.canvas.width = W;
      this.canvas.height = H;
    }
    gl.viewport(0, 0, w, h);
    gl.useProgram(p.program);
    for (const [name, v] of Object.entries(uniforms)) {
      if (!p.loc.has(name)) p.loc.set(name, gl.getUniformLocation(p.program, name));
      const loc = p.loc.get(name);
      if (!loc) continue;
      if (name === "u_seed") gl.uniform1ui(loc, v as number);
      else if (Array.isArray(v)) (v.length === 2 ? gl.uniform2fv : gl.uniform3fv).call(gl, loc, v);
      else gl.uniform1f(loc, v);
    }
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    return true;
  }

  dispose() {
    this.gl?.getExtension("WEBGL_lose_context")?.loseContext();
    this.gl = null;
    this.programs.clear();
  }
}

// --- Target --------------------------------------------------------------------

/** Targets larger than this (CSS px²) step down in resolution when frames get slow. */
const BIG_AREA = 40_000;

class Target {
  readonly canvas = document.createElement("canvas");
  private readonly ctx = this.canvas.getContext("2d")!;
  /** Where the canvas lives; it covers this element's border box. */
  readonly mount: HTMLElement;
  values: Values = {};
  clock: number;
  speed = 1;
  visible = true;
  dirty = true;
  /** Null until the first frame publishes one, so even "floor" is said out loud. */
  state: ShaderState | null = null;
  w = 0;
  h = 0;
  cssW = 0;
  cssH = 0;
  dpr = 1;
  /** Live-value transitions in flight on this canvas. */
  easing = 0;
  /** When this target last painted while moving (ms), for `def.fps`. */
  painted = 0;
  private radius = 0;
  private readonly restore: Array<() => void> = [];

  constructor(
    readonly root: HTMLElement,
    /** The rounded box the shader draws. */
    readonly part: HTMLElement,
    readonly def: ShaderDef,
    readonly recipe: ShaderRecipe,
    readonly seed: number,
    private readonly scheduler: Scheduler,
  ) {
    this.clock = def.restTime;
    this.canvas.className = `ui-fx-canvas ui-fx-canvas-${def.name}`;
    this.canvas.setAttribute("aria-hidden", "true");
    this.mount =
      recipe.mount === "root" ? root : recipe.mount ? (root.querySelector<HTMLElement>(recipe.mount) ?? part) : part;

    // The mount must contain an absolutely positioned child; an UNDER canvas
    // also needs a stacking context so z-index -1 lands above the mount's own
    // background. Both are put back on unmount.
    const style = this.mount.style;
    const hadStyle = this.mount.hasAttribute("style");
    this.restore.push(() => {
      if (!hadStyle && this.mount.getAttribute("style") === "") this.mount.removeAttribute("style");
    });
    if (getComputedStyle(this.mount).position === "static") {
      const prev = style.position;
      style.position = "relative";
      this.restore.push(() => (style.position = prev));
    }
    if (recipe.layer === "over") this.canvas.classList.add("ui-fx-canvas-over");
    else {
      const prev = style.isolation;
      style.isolation = "isolate";
      this.restore.push(() => (style.isolation = prev));
    }

    // State values (--ui-fx-halo-strength) are read every frame
    // only while the canvas is transitioning one of them, so they follow the
    // component's own motion token. At rest a target costs no style read.
    this.canvas.addEventListener("transitionrun", (e) => {
      if (!e.propertyName.startsWith("--ui-fx-")) return;
      this.easing++;
      this.scheduler.wake();
    });
    const settle = (e: TransitionEvent) => {
      if (!e.propertyName.startsWith("--ui-fx-")) return;
      this.easing = Math.max(0, this.easing - 1);
      this.readLive();
      this.scheduler.wake();
    };
    this.canvas.addEventListener("transitionend", settle);
    this.canvas.addEventListener("transitioncancel", settle);

    if (recipe.layer === "over" && this.mount !== part && part.parentElement === this.mount) part.after(this.canvas);
    else this.mount.appendChild(this.canvas);
    this.refresh();
  }

  setState(s: ShaderState) {
    if (this.state === s) return;
    this.state = s;
    this.dirty = true;
    this.root.setAttribute(`data-fx-${this.def.name}`, s);
  }

  /** Re-read every token. Theme, scheme and class changes call this. */
  refresh() {
    for (const [name, spec] of Object.entries(this.def.uniforms)) {
      this.values[name] =
        "color" in spec
          ? readColor(this.canvas, spec.color, spec.fallback)
          : "keyword" in spec
            ? readKeyword(this.canvas, spec.keyword, spec.values)
            : readNumber(this.canvas, spec.number, spec.fallback ?? 0);
    }
    this.def.resolve?.(this.values);
    this.speed = readNumber(this.canvas, "--ui-fx-ambient-speed", 1);
    this.layout();
  }

  readLive() {
    for (const [name, spec] of Object.entries(this.def.uniforms)) {
      if (!("number" in spec) || !spec.live) continue;
      const v = readNumber(this.canvas, spec.number, spec.fallback ?? 0);
      // Object.is: a NaN (`auto`) must not read as a change on every frame.
      if (!Object.is(v, this.values[name])) {
        this.values[name] = v;
        this.dirty = true;
      }
    }
    this.def.resolve?.(this.values);
  }

  layout(quality = this.scheduler.quality) {
    const bleed = this.def.bleed ?? 0;
    const m = this.mount;
    // LAYOUT size, not the transformed box: a pressed Button is scaled by
    // --ui-press-scale and its canvas scales with it.
    this.cssW = m.offsetWidth + 2 * bleed;
    this.cssH = m.offsetHeight + 2 * bleed;
    const s = this.canvas.style;
    // An absolutely positioned child is placed from the PADDING box; the
    // canvas covers the BORDER box, so it steps back over the border.
    s.left = `${-m.clientLeft - bleed}px`;
    s.top = `${-m.clientTop - bleed}px`;
    s.width = `${this.cssW}px`;
    s.height = `${this.cssH}px`;
    const big = this.cssW * this.cssH > BIG_AREA && this.def.adaptive !== false;
    this.dpr = Math.min(devicePixelRatio || 1, settings.maxDpr) * (big ? quality : 1);
    const w = Math.max(1, Math.round(this.cssW * this.dpr));
    const h = Math.max(1, Math.round(this.cssH * this.dpr));
    if (w !== this.canvas.width || h !== this.canvas.height) {
      this.canvas.width = this.w = w;
      this.canvas.height = this.h = h;
    }
    this.values.u_bleed = bleed;
    this.radius = parseFloat(getComputedStyle(this.part).borderTopLeftRadius) || 0;
    this.measureShape();
    this.dirty = true;
  }

  /**
   * The shape's box in canvas CSS px, y up (GL). Measured every frame for a
   * shape that moves inside its mount: a Progress fill growing through its
   * transition, a Slider fill under the pointer.
   */
  measureShape() {
    const bleed = this.def.bleed ?? 0;
    let x = 0;
    let y = 0;
    let w = this.mount.offsetWidth;
    let h = this.mount.offsetHeight;
    if (this.part !== this.mount) {
      const mr = this.mount.getBoundingClientRect();
      const k = mr.width / (this.mount.offsetWidth || 1) || 1;
      const r = this.part.getBoundingClientRect();
      x = (r.left - mr.left) / k;
      y = (r.top - mr.top) / k;
      w = r.width / k;
      h = r.height / k;
    }
    const center = [bleed + x + w / 2, this.cssH - (bleed + y + h / 2)];
    const box = [w / 2, h / 2];
    const prev = this.values.u_center as number[] | undefined;
    const prevBox = this.values.u_box as number[] | undefined;
    if (prev?.[0] === center[0] && prev?.[1] === center[1] && prevBox?.[0] === box[0] && prevBox?.[1] === box[1]) return;
    this.values.u_center = center;
    this.values.u_box = box;
    this.values.u_radius = Math.min(this.radius, w / 2, h / 2);
    this.dirty = true;
  }

  paint(renderer: Renderer): boolean {
    const uniforms: Values = {
      ...this.values,
      u_resolution: [this.w, this.h],
      u_time: this.clock,
      u_dpr: this.dpr,
      u_seed: this.seed,
    };
    if (!renderer.draw(this.def, this.w, this.h, uniforms)) return false;
    this.ctx.globalCompositeOperation = "copy";
    // GL rows start at the bottom: the drawn region is the bottom-left corner.
    this.ctx.drawImage(renderer.canvas, 0, renderer.canvas.height - this.h, this.w, this.h, 0, 0, this.w, this.h);
    this.ctx.globalCompositeOperation = "source-over";
    this.dirty = false;
    return true;
  }

  /** The last frame's pixels, premultiplied. What a contrast test samples. */
  pixels(): ImageData {
    return this.ctx.getImageData(0, 0, this.w, this.h);
  }

  unmount() {
    this.canvas.remove();
    this.root.removeAttribute(`data-fx-${this.def.name}`);
    // Last in, first out: the attribute check runs after the values are back.
    for (const undo of this.restore.splice(0).reverse()) undo();
  }
}

// --- Scheduler ----------------------------------------------------------------

class Scheduler {
  readonly renderer: Renderer;
  readonly targets = new Set<Target>();
  /** The adaptive step, 1 down to 0.5. `settings.quality` overrides it. */
  private adaptive = 1;
  get quality() {
    return settings.quality ?? this.adaptive;
  }
  private byRoot = new WeakMap<HTMLElement, Map<ShaderName, Target>>();
  private byMount = new Map<Element, Set<Target>>();
  private seed = 1;
  private raf = 0;
  private last = 0;
  private frames = 0;
  private spent = 0;
  private since = 0;
  private refreshQueued = false;
  /** Set by stop(). A font load or a queued refresh still in flight must not
   *  resurrect canvases into the next page — found by the refcount test. */
  private stopped = false;
  private pending = new Set<Element>();
  private readonly teardown: Array<() => void> = [];
  private readonly reducedMotion = matchMedia("(prefers-reduced-motion: reduce)");
  /** Forced colours hide every canvas (shader.css): draw nothing, as at the floor. */
  private readonly forcedColors = matchMedia("(forced-colors: active)");

  private intersection = new IntersectionObserver(
    (entries) => {
      for (const e of entries) {
        for (const t of this.byMount.get(e.target) ?? []) {
          t.visible = e.isIntersecting;
          if (t.visible) t.dirty = true;
        }
      }
      this.wake();
    },
    { rootMargin: "160px" },
  );

  private resize = new ResizeObserver((entries) => {
    for (const e of entries) {
      for (const t of this.targets) if (t.mount === e.target || t.part === e.target) t.layout();
    }
    this.wake();
  });

  constructor() {
    this.renderer = new Renderer(() => {
      for (const t of this.targets) t.dirty = true;
      this.wake();
    });
  }

  private isStill() {
    return settings.freezeAt !== null || (settings.reducedMotion ?? this.reducedMotion.matches);
  }

  start() {
    this.sweep();

    // The runtime writes styles on its own canvases and mounts and appends
    // canvases: those mutations must not schedule another read.
    const ours = (n: Node) => n instanceof HTMLCanvasElement && n.classList.contains("ui-fx-canvas");
    const observer = new MutationObserver((records) => {
      let added = false;
      for (const r of records) {
        if (r.type === "childList") {
          if (![...r.addedNodes, ...r.removedNodes].every(ours)) added = true;
          continue;
        }
        if (ours(r.target)) continue;
        // Geometry is the observers' business: a Slider fill's inline width
        // changes on every pointer move, and re-reading tokens for it would
        // cost a style read per uniform per frame of a drag. But an inline
        // TOKEN on the same element — `style={{ "--ui-fx-gradient-intensity":
        // 0.5 }}` on a ground — is a token change like any other.
        if (r.attributeName === "style" && this.geometry(r.target as Element)) {
          const tokens = (css: string | null) => (css?.match(/--[\w-]+\s*:[^;]*/g) ?? []).join(";");
          if (tokens(r.oldValue) === tokens((r.target as Element).getAttribute("style"))) continue;
        }
        this.pending.add(r.target as Element);
      }
      if (added || this.pending.size) this.queueRefresh(added);
    });
    observer.observe(document.documentElement, {
      subtree: true,
      childList: true,
      attributes: true,
      attributeOldValue: true,
      // What can change a token or an effect class: a class, an inline style,
      // and the attributes the token emitter scopes brands and schemes with.
      attributeFilter: ["class", "style", "data-ui-theme", "data-theme", "data-scheme", "data-color-scheme"],
    });
    this.teardown.push(() => observer.disconnect());

    const all = () => {
      this.pending.add(document.documentElement);
      this.queueRefresh(false);
    };
    const scheme = matchMedia("(prefers-color-scheme: dark)");
    scheme.addEventListener("change", all);
    this.reducedMotion.addEventListener("change", all);
    this.forcedColors.addEventListener("change", all);
    this.teardown.push(() => {
      scheme.removeEventListener("change", all);
      this.reducedMotion.removeEventListener("change", all);
      this.forcedColors.removeEventListener("change", all);
    });
    void document.fonts?.ready.then(() => this.targets.size && all());
    this.wake();
  }

  stop() {
    this.stopped = true;
    cancelAnimationFrame(this.raf);
    this.raf = 0;
    for (const undo of this.teardown.splice(0)) undo();
    this.intersection.disconnect();
    this.resize.disconnect();
    for (const t of this.targets) t.unmount();
    this.targets.clear();
    this.byMount.clear();
    this.byRoot = new WeakMap();
    this.renderer.dispose();
  }

  /** Is `el` a part or a mount — something the runtime measures rather than reads? */
  private geometry(el: Element) {
    if (this.byMount.has(el)) return true;
    for (const t of this.targets) if (t.part === el) return true;
    return false;
  }

  private attach(root: HTMLElement) {
    let mine = this.byRoot.get(root);
    if (!mine) this.byRoot.set(root, (mine = new Map()));
    for (const name of NAMES) {
      if (!root.classList.contains(`fx-${name}`) || mine.has(name)) continue;
      const recipes = SHADER_RECIPES[name];
      const slot = root.dataset.slot;
      const recipe = (slot ? recipes[slot] : undefined) ?? recipes["*"]!;
      const part = recipe.part ? root.querySelector<HTMLElement>(recipe.part) : root;
      if (!part) continue;
      const t = new Target(root, part, SHADERS[name], recipe, this.seed++, this);
      mine.set(name, t);
      this.targets.add(t);
      let set = this.byMount.get(t.mount);
      if (!set) this.byMount.set(t.mount, (set = new Set()));
      set.add(t);
      this.intersection.observe(t.mount);
      this.resize.observe(t.mount);
      if (t.mount !== part) this.resize.observe(part);
    }
  }

  private detach(t: Target) {
    t.unmount();
    this.targets.delete(t);
    this.byRoot.get(t.root)?.delete(t.def.name);
    const set = this.byMount.get(t.mount);
    set?.delete(t);
    if (set && !set.size) {
      this.byMount.delete(t.mount);
      this.intersection.unobserve(t.mount);
      this.resize.unobserve(t.mount);
    }
  }

  private sweep() {
    for (const t of [...this.targets]) {
      const stillThere = t.root.isConnected && t.part.isConnected && t.root.classList.contains(`fx-${t.def.name}`);
      if (!stillThere) this.detach(t);
    }
    for (const el of document.querySelectorAll<HTMLElement>(SELECTOR)) this.attach(el);
  }

  /**
   * Batched to the next frame. A changed element re-reads only the targets
   * it can reach: its own subtree, or an ancestor's (a class on <html> moves
   * every token beneath it). Typing in a field re-reads nothing.
   */
  private queueRefresh(sweep: boolean) {
    if (this.stopped) return;
    if (sweep) this.pending.add(document.documentElement);
    if (this.refreshQueued) return;
    this.refreshQueued = true;
    requestAnimationFrame(() => {
      this.refreshQueued = false;
      if (this.stopped) return;
      const changed = [...this.pending];
      this.pending.clear();
      this.sweep();
      for (const t of this.targets) {
        if (changed.some((el) => el.contains(t.root) || t.root.contains(el))) t.refresh();
      }
      this.wake();
    });
  }

  /** Schedule a frame if none is pending. The loop sleeps while nothing moves. */
  wake() {
    if (this.stopped || this.raf || !this.targets.size) return;
    this.raf = requestAnimationFrame((now) => this.frame(now));
  }

  private frame(now: number) {
    this.raf = 0;
    const dt = this.last ? Math.min(0.1, (now - this.last) / 1000) : 0;
    this.last = now;
    const t0 = performance.now();
    const still = this.isStill();
    const floor = settings.forceFloor || this.forcedColors.matches;
    const usable = !floor && this.renderer.init();
    const offState: ShaderState = floor
      ? "floor"
      : this.renderer.lost
        ? "lost"
        : this.renderer.gl
          ? "floor"
          : "unsupported";
    let moving = false;
    let painted = 0;
    for (const t of this.targets) {
      if (!usable) {
        t.setState(offState);
        continue;
      }
      t.setState(still ? "still" : "live");
      if (!t.visible) continue;
      if (t.easing) {
        t.readLive();
        moving = true;
      }
      if (t.part !== t.mount) t.measureShape();
      if (t.def.idle?.(t.values) && !t.dirty) continue;
      if (still) {
        const at = settings.freezeAt ?? t.def.restTime;
        if (t.clock !== at) {
          t.clock = at;
          t.dirty = true;
        }
        if (t.dirty && t.paint(this.renderer)) painted++;
        continue;
      }
      t.clock += dt * t.speed;
      moving = true;
      // A capped target keeps its clock running and paints when its turn
      // comes; a state change (dirty) never waits.
      if (t.def.fps && !t.dirty && now - t.painted < 1000 / t.def.fps - 2) continue;
      t.painted = now;
      if (t.paint(this.renderer)) painted++;
    }
    // Only frames that painted say what painting costs: averaging in the
    // frames a capped ground skips would halve its cost on paper.
    if (painted) this.measure(now, performance.now() - t0);
    // The loop sleeps once nothing moves: still targets are drawn once, an
    // idle halo not at all. Anything that changes a target — a transition on
    // the canvas, a resize, a token, visibility — wakes it again. With no
    // usable context there is nothing to wake for until it comes back.
    if (usable && (moving || [...this.targets].some((t) => t.dirty && t.visible))) this.wake();
    else this.last = 0;
  }

  /**
   * Adaptive quality. Full device resolution by default. Only when frames
   * get slow do LARGE targets step down, a quarter at a time, and step back
   * up once there is room. Small controls always render at full resolution,
   * and so does a target whose program says `adaptive: false` (a ground: a
   * scaled dither smears). `settings.quality` pins the step instead.
   */
  private measure(now: number, ms: number) {
    if (settings.quality !== null) return;
    if (!this.since) this.since = now;
    this.spent += ms;
    this.frames++;
    if (now - this.since < 500) return;
    const per = this.spent / this.frames;
    this.frames = 0;
    this.spent = 0;
    this.since = now;
    const next = per > 12 ? Math.max(0.5, this.adaptive - 0.25) : per < 5 ? Math.min(1, this.adaptive + 0.25) : this.adaptive;
    if (next === this.adaptive) return;
    this.adaptive = next;
    for (const t of this.targets) if (t.cssW * t.cssH > BIG_AREA && t.def.adaptive !== false) t.layout(next);
  }

  /** Draw a target now and read its pixels back. */
  sample(root: HTMLElement, name: ShaderName) {
    const t = this.byRoot.get(root)?.get(name);
    if (!t || !t.paint(this.renderer)) return null;
    const { data } = t.pixels();
    return { data, width: t.w, height: t.h, dpr: t.dpr, values: { ...t.values } };
  }
}

// --- public API --------------------------------------------------------------

let scheduler: Scheduler | null = null;
let starts = 0;

/**
 * Start the runtime and return its stop function. Safe to call on the
 * server (it does nothing there) and more than once: it counts its callers
 * and stops when the last one has, so React's StrictMode double effect, or
 * two islands that each start it, share one runtime.
 */
export function startShaders(): () => void {
  if (typeof window === "undefined" || typeof document === "undefined") return () => {};
  if (typeof IntersectionObserver === "undefined" || typeof ResizeObserver === "undefined") return () => {};
  starts++;
  if (!scheduler) {
    scheduler = new Scheduler();
    scheduler.start();
  }
  let stopped = false;
  return () => {
    if (stopped) return;
    stopped = true;
    if (--starts > 0 || !scheduler) return;
    scheduler.stop();
    scheduler = null;
  };
}

/** Override what the runtime would detect — for stories, tests and screenshots. */
export function configureShaders(next: Partial<ShaderSettings>): void {
  Object.assign(settings, next);
  if (!scheduler) return;
  for (const t of scheduler.targets) {
    t.dirty = true;
    t.layout();
  }
  scheduler.wake();
}

/**
 * Draw the effect on `root` now and return its pixels (premultiplied RGBA,
 * device px) and the uniform values it drew with, `auto` already resolved —
 * or null if it is not drawing. What a contrast test samples:
 * the guard is only as good as the measurement that holds it.
 */
export function sampleShader(root: HTMLElement, name: ShaderName) {
  return scheduler?.sample(root, name) ?? null;
}

/**
 * The shader programs of the effects layer (ADR 0022, ADR 0025): the
 * gradient — one parametric ground in five looks (wash, sweep, fold, rise,
 * dawn) — and halo, and the GLSL they share. Paired with `@/lib/shader`,
 * which runs them.
 *
 * THE ADMISSION RULE, which `pnpm check:fx` enforces on this file:
 *
 *   1. A shader paints only pixels it owns — its part's fill, or a ground.
 *      It never reads the page, a backdrop or another canvas: no sampler2D,
 *      no texture(). (Refraction failed exactly here, twice.)
 *   2. Every input is a token, read where the part sits: every uniform below
 *      names a `--…` custom property.
 *   3. Its floor is the component. Nothing here draws what the component
 *      does not already show; it only paints over a fill that exists.
 *   4. It keeps the ink on its part legible, and the browser test samples
 *      the result. A ground does it with a QUIET ZONE (ADR 0025): around the
 *      copy's anchor it paints exactly its base, so the ink keeps the
 *      contrast the token pair was audited at, and the light outside the
 *      zone is free to be bright. (A per-pixel guard, aurora's way, held the
 *      ratio only by squeezing a dark ground into a handful of grey levels.)
 *
 * Every program ends the same way: mixed in OKLab, encoded to sRGB, then a
 * static triangular-PDF dither of one 8-bit step, so a slow ramp never shows
 * bands (Playdead, "Banding in Games": dither last, in the space the value is
 * quantised in).
 *
 * The GLSL prelude — hashing, noise, OKLab, the shape — is kept as measured
 * in the effects lab. Hash: lowbias32 by Chris Wellons (public domain).
 * OKLab: Björn Ottosson's published matrices (public domain). The grounds
 * were written for this library (docs/webgl-gradients.md); other gradient
 * libraries were a benchmark only, and no code was taken from them.
 */

import type { ShaderFxName } from "@/lib/fx";

export type ShaderName = ShaderFxName;

/**
 * A uniform's source: a colour token, a numeric one, or a KEYWORD one (its
 * value is one of `values`, sent as its index). `live` ones follow a CSS
 * transition. A numeric token set to `auto` reads as its fallback; NaN as a
 * fallback means "the look decides", filled in by the program's `resolve`.
 */
export type UniformSpec =
  | { color: string; fallback?: string }
  | { number: string; fallback?: number; live?: boolean }
  | { keyword: string; values: readonly string[] };

export type UniformValues = Record<string, number | number[]>;

export interface ShaderDef {
  name: ShaderName;
  fragment: string;
  /** Every uniform names a token (rule 2). */
  uniforms: Record<string, UniformSpec>;
  /** The frame shown under reduced motion: chosen, not t = 0. */
  restTime: number;
  /** CSS px the canvas reaches past its part, for a light that falls off. */
  bleed?: number;
  /**
   * False keeps the target at full resolution when frames get slow. A ground
   * dithers per device pixel; scaled up, the dither smears and the bands it
   * hides come back. Default true.
   */
  adaptive?: boolean;
  /** Frames per second at most. A ground moves slowly; 30 halves its cost unseen. */
  fps?: number;
  /** Skip drawing while this holds (a halo faded to nothing costs nothing). */
  idle?: (values: UniformValues) => boolean;
  /** Fill in what the tokens left to the program (`auto`): a look's own preset. */
  resolve?: (values: UniformValues) => void;
}

export const VERTEX = `#version 300 es
// One triangle that covers the viewport: (-1,-1) (3,-1) (-1,3). No buffers.
void main() {
  vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));
  gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
}`;

// highp on purpose: mediump float is fp16 on many phone GPUs (noise turns to
// blocks past ~2048) and mediump int is 16-bit (every integer hash breaks).
// Desktop GPUs run mediump as highp, so the bug hides where shaders are written.
export const PRELUDE = `#version 300 es
precision highp float;
precision highp int;

uniform vec2  u_resolution;  // drawing size, device px
uniform float u_time;        // seconds, scaled by the motion knob
uniform float u_dpr;
uniform uint  u_seed;
out vec4 fragColor;

// lowbias32 (Chris Wellons, public domain): integer hashing, stable across GPUs.
uint fx_hash(uint x) {
  x ^= x >> 16; x *= 0x7feb352du; x ^= x >> 15; x *= 0x846ca68bu; x ^= x >> 16; return x;
}
uint fx_hash(uvec3 v) { return fx_hash(v.x ^ fx_hash(v.y ^ fx_hash(v.z ^ u_seed))); }
float fx_rand(uvec3 v) { return float(fx_hash(v)) * (1.0 / 4294967295.0); }

vec2 fx_grad(ivec2 c, uint salt) {
  float a = fx_rand(uvec3(uvec2(c + 65536), salt)) * 6.2831853;
  return vec2(cos(a), sin(a));
}
float fx_noise(vec2 p, uint salt) {
  ivec2 i = ivec2(floor(p)); vec2 f = fract(p);
  vec2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  float a = dot(fx_grad(i, salt), f);
  float b = dot(fx_grad(i + ivec2(1, 0), salt), f - vec2(1.0, 0.0));
  float c = dot(fx_grad(i + ivec2(0, 1), salt), f - vec2(0.0, 1.0));
  float d = dot(fx_grad(i + ivec2(1, 1), salt), f - vec2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
// sRGB <-> OKLab (Bjorn Ottosson's published matrices).
vec3 fx_toLinear(vec3 c) { return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(0.04045, c)); }
vec3 fx_toSrgb(vec3 c) { c = clamp(c, 0.0, 1.0); return mix(c * 12.92, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, step(0.0031308, c)); }
vec3 fx_oklab(vec3 srgb) {
  vec3 c = fx_toLinear(srgb);
  float l = pow(max(0.4122214708 * c.r + 0.5363325363 * c.g + 0.0514459929 * c.b, 0.0), 1.0 / 3.0);
  float m = pow(max(0.2119034982 * c.r + 0.6806995451 * c.g + 0.1073969566 * c.b, 0.0), 1.0 / 3.0);
  float s = pow(max(0.0883024619 * c.r + 0.2817188376 * c.g + 0.6299787005 * c.b, 0.0), 1.0 / 3.0);
  return vec3(0.2104542553 * l + 0.7936177850 * m - 0.0040720468 * s,
              1.9779984951 * l - 2.4285922050 * m + 0.4505937099 * s,
              0.0259040371 * l + 0.7827717662 * m - 0.8086757660 * s);
}
vec3 fx_srgb(vec3 lab) {
  float l = lab.x + 0.3963377774 * lab.y + 0.2158037573 * lab.z;
  float m = lab.x - 0.1055613458 * lab.y - 0.0638541728 * lab.z;
  float s = lab.x - 0.0894841775 * lab.y - 1.2914855480 * lab.z;
  l = l * l * l; m = m * m * m; s = s * s * s;
  return fx_toSrgb(vec3(4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
                       -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
                       -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s));
}
vec3 fx_hueTurn(vec3 lab, float r) { float c = cos(r), s = sin(r); return vec3(lab.x, c * lab.y - s * lab.z, s * lab.y + c * lab.z); }
// Static triangular-PDF dither in [-1, 1] of one step (two uniform draws):
// no pixel is left without noise, unlike a uniform draw. Static, because a
// slow ground has no motion to hide a dither that changes every frame.
float fx_tpdf(vec2 px) {
  uvec2 p = uvec2(px);
  return fx_rand(uvec3(p, 101u)) + fx_rand(uvec3(p, 102u)) - 1.0;
}

float fx_roundBox(vec2 p, vec2 halfSize, float r) {
  vec2 q = abs(p) - halfSize + r;
  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}

// The shape: the part's own rounded box, in canvas CSS px (y up). The shader
// draws it, antialiased to one device pixel, so nothing depends on CSS
// clipping a canvas (which iOS Safari drops while a layer animates).
uniform vec2  u_center;
uniform vec2  u_box;
uniform float u_radius;
float fx_shapeDistance(vec2 css) { return fx_roundBox(css - u_center, u_box, u_radius); }
float fx_cover(float d) { return clamp(0.5 - d * u_dpr, 0.0, 1.0); }
`;

/**
 * THE GRADIENT (ADR 0025): one ground, parametric. A look picks the form —
 * wash, sweep, fold, rise or dawn — and every other knob is shared: the two
 * colours, angle, sharpness, scale, chroma, intensity, the quiet zone, the
 * edge, grain. Four knobs follow the look when left at `auto`: angle,
 * intensity, and the quiet zone's size and height (GRADIENT_PRESETS) — so
 * `--ui-fx-gradient-look: rise` alone is a finished horizon. The rest have
 * one default for every look. Every knob is clamped to the range its GLSL is
 * written for. The looks do not blend into each other (they are different
 * forms), but everything around the form is the same code.
 *
 * The palette is the two tokens and nothing else: the base it replaces and
 * the light moving over it. Every other tone is derived in OKLab.
 */
export const GRADIENT_LOOKS = ["wash", "sweep", "fold", "rise", "dawn"] as const;
export type GradientLook = (typeof GRADIENT_LOOKS)[number];

/** What `auto` means, per look. */
export const GRADIENT_PRESETS: Record<GradientLook, { angle: number; intensity: number; quiet: number; quietY: number }> = {
  /** A calm field that fills the frame. */
  wash: { angle: 0, intensity: 1, quiet: 0.42, quietY: 0.9 },
  /** Two big S-shaped forms, each lit across its body. */
  sweep: { angle: -28, intensity: 1, quiet: 0.42, quietY: 0.9 },
  /** Light panes along slow folds, a soft body and a sharp lit rim. */
  fold: { angle: 24, intensity: 0.85, quiet: 0.42, quietY: 0.9 },
  /**
   * A horizon: a bright rim low in the frame, glow above, body below. Copy
   * goes in the sky, and the zone is smaller: the sky is already quiet, and
   * a large ellipse there reaches down into the light.
   */
  rise: { angle: 0, intensity: 1, quiet: 0.3, quietY: 0.18 },
  /** A soft horizon: light rising from below the frame, no rim. Copy goes in the sky. */
  dawn: { angle: 0, intensity: 1, quiet: 0.3, quietY: 0.18 },
};

const GRADIENT = `
uniform vec3  u_base;       // the ground the light sits on
uniform vec3  u_light;      // the brand light
uniform float u_look;       // 0 wash, 1 sweep, 2 fold, 3 rise, 4 dawn
uniform float u_angle;      // degrees: the direction the forms run
uniform float u_sharpness;  // 0..1; 0.5 is the look's own edges and rims
uniform float u_scale;      // the forms' size; 1 is the look's own
uniform float u_chroma;     // colourfulness; 1 is the look's own
uniform float u_intensity;  // 0 = the base alone, 1 = the full field
uniform float u_quiet;      // quiet zone radius, as a fraction of the width; 0 = none
uniform float u_quietX;     // its centre, 0..1 across the box, left to right
uniform float u_quietY;     // and 0..1 down the box, top to bottom (as CSS reads it)
uniform float u_dissolve;   // 0 = fill to the edge; >0 = fraction of the short side the light fades over
uniform float u_grain;      // visible film grain; 0 = none (the dither is always on)

// The box in CSS px, y up (GL), and the field: x 0..1 across, y 0..aspect.
vec2 fx_local() { return gl_FragCoord.xy / u_dpr - (u_center - u_box); }
float fx_aspect() { return u_box.y / max(u_box.x, 1.0); }
float fx_isDark() { return fx_oklab(u_base).x < 0.5 ? 1.0 : 0.0; }
// Sharpness as a factor: 0.25 at 0, 1 at 0.5, 4 at 1.
float fx_sharp() { return exp2((u_sharpness - 0.5) * 4.0); }
// The field turned by the angle and sized by the scale, about its centre.
vec2 fx_frame(vec2 uv) {
  vec2 c = vec2(0.5, 0.5 * fx_aspect());
  float a = radians(u_angle);
  return mat2(cos(a), sin(a), -sin(a), cos(a)) * (uv - c) / max(u_scale, 0.05);
}

// A tone derived from the accent: a lightness, and its chroma scaled. Chroma
// shrinks as the tone darkens — a dark tone at full chroma reads electric,
// and a dark yellow at any real chroma reads olive.
vec3 fx_tone(vec3 accent, float lightness, float chroma) {
  return vec3(lightness, accent.yz * chroma * u_chroma * mix(0.45, 1.0, smoothstep(0.3, 0.85, lightness)));
}
// Shadows turn AWAY from yellow-green: a blue accent's go royal, a yellow's
// go amber instead of olive. +1 or -1: the direction a darker tone turns.
float fx_shadowTurn(vec3 accent) {
  float h = degrees(atan(accent.z, accent.y));
  h = h < 0.0 ? h + 360.0 : h;
  return (h > 110.0 && h < 290.0) ? 1.0 : -1.0;
}

// 0 inside the quiet zone's core (the copy), 1 outside it. An ellipse wider
// than tall, because a block of copy is. The core is HALF the radius, so the
// whole copy block sits on the exact base, then the field comes in.
vec2 fx_anchor() { return vec2(u_quietX, (1.0 - u_quietY) * fx_aspect()); }
float fx_quietMask(vec2 uv) {
  if (u_quiet <= 0.0) return 1.0;
  float d = length((uv - fx_anchor()) * vec2(0.75, 1.5));
  return smoothstep(0.5 * u_quiet, u_quiet, d);
}
// On a look that fills the frame, an ellipse of base reads as a stain. These
// make the quiet side part of the composition: light falling away toward the
// copy over a long reach, or light from a direction.
float fx_falloff(vec2 uv) {
  if (u_quiet <= 0.0) return 1.0;
  float d = length((uv - fx_anchor()) * vec2(0.75, 1.5));
  return smoothstep(0.35 * u_quiet, 1.6 * u_quiet, d);
}
float fx_lightFrom(vec2 uv) {
  if (u_quiet <= 0.0) return 1.0;
  return smoothstep(0.02, 0.62, dot(uv - fx_anchor(), normalize(vec2(1.0, 0.75))));
}

// Separable: the product of two 1D falloffs is smooth everywhere. A fade by
// the box's distance field creases along its diagonals (the mitre the lab
// measured in the retired aurora's dissolve).
float fx_edgeMask(vec2 local) {
  if (u_dissolve <= 0.0) return 1.0;
  vec2 reach = vec2(max(u_dissolve * 2.0 * min(u_box.x, u_box.y), 1.0));
  vec2 e = clamp(min(local, 2.0 * u_box - local) / reach, 0.0, 1.0);
  vec2 s = smoothstep(0.0, 1.0, e);
  return s.x * s.y;
}

// ---- the looks: each returns the field's colour in OKLab

// WASH: broad gaussian pools drifting over a ramp between two derived tones.
// No point is small, so nothing reads as a spot.
vec3 fx_wash(vec2 uv, float t, float dk, vec3 B, vec3 A) {
  float k = fx_aspect();
  vec2 p = fx_frame(uv) + vec2(0.5, 0.5 * k);
  vec3 deep = fx_tone(A, mix(0.74, 0.46, dk), mix(1.35, 1.7, dk));
  vec3 mid = fx_tone(fx_hueTurn(A, radians(16.0)), mix(0.86, 0.64, dk), mix(1.2, 1.5, dk));
  vec3 pale = fx_tone(A, mix(0.95, 0.80, dk), 0.9);
  vec3 ramp = mix(deep, mid, smoothstep(0.0, k, p.y));
  vec2 P[4]; vec3 C[4];
  P[0] = vec2(0.25, 0.75 * k) + 0.18 * vec2(sin(0.7 * t), cos(0.5 * t));             C[0] = pale;
  P[1] = vec2(0.75, 0.30 * k) + 0.20 * vec2(cos(0.6 * t + 1.0), sin(0.4 * t));       C[1] = deep;
  P[2] = vec2(0.85, 0.85 * k) + 0.16 * vec2(sin(0.5 * t + 2.0), cos(0.7 * t));       C[2] = mid;
  P[3] = vec2(0.45, 0.25 * k) + 0.18 * vec2(cos(0.4 * t + 3.0), sin(0.6 * t + 1.0)); C[3] = fx_tone(fx_hueTurn(A, radians(-14.0)), mix(0.80, 0.52, dk), 1.25);
  float spread = 0.09 / fx_sharp();  // sharper: tighter pools
  vec3 sum = ramp * 0.25; float wsum = 0.25;
  for (int i = 0; i < 4; i++) {
    vec2 d = p - P[i];
    float w = exp(-dot(d, d) / spread);
    sum += w * C[i]; wsum += w;
  }
  return mix(B, sum / wsum, fx_falloff(uv));
}

// SWEEP: two big S-shaped forms, each lit across its body — brightest at its
// edge — with a shadow cast in front of the edge.
float fx_sweepForm(vec2 q, float t, float phase, float amp) {
  return q.y - amp * sin(1.15 * q.x + 0.35 * t + phase) - 0.18 * sin(2.3 * q.x - 0.25 * t + 2.0 * phase);
}
vec3 fx_sweep(vec2 uv, float t, float dk, vec3 B, vec3 A) {
  vec2 q = fx_frame(uv) * 2.2;
  float sh = fx_sharp();
  vec3 lab;
  if (dk > 0.5) {
    // Dark stays inside the accent's hue family: mixing the light into a warm
    // near-black base reads as grey-teal fog. The base returns only under the copy.
    float dir = fx_shadowTurn(A);
    vec3 navy = fx_tone(fx_hueTurn(A, radians(22.0 * dir)), 0.20, 0.55);
    vec3 blue = fx_tone(fx_hueTurn(A, radians(18.0 * dir)), 0.56, 1.8);
    vec3 cyan = fx_tone(fx_hueTurn(A, radians(-10.0 * dir)), 0.82, 1.45);
    vec3 hi = fx_tone(fx_hueTurn(A, radians(-6.0 * dir)), 0.95, 0.9);
    lab = mix(navy, blue, 0.25 + 0.3 * smoothstep(-1.2, 1.2, q.y));
    for (int i = 0; i < 2; i++) {
      float fi = float(i);
      float f = fx_sweepForm(q + vec2(0.0, 0.55 - 1.1 * fi), t, 1.7 * fi, 0.55 - 0.15 * fi);
      float inside = smoothstep(-0.012 / sh, 0.03 / sh, f);
      lab = mix(lab, navy, (1.0 - inside) * exp(-max(-f, 0.0) * 3.2) * 0.75);
      float body = exp(-max(f, 0.0) * 1.1);
      vec3 tone = fi < 0.5 ? mix(blue, cyan, body) : mix(navy, blue, 0.35 + 0.65 * body);
      tone = mix(tone, hi, exp(-max(f, 0.0) * 14.0 * sh) * (fi < 0.5 ? 0.55 : 0.25));
      lab = mix(lab, tone, inside);
    }
    return mix(navy, lab, fx_lightFrom(uv));
  }
  vec3 deep = fx_tone(fx_hueTurn(A, radians(-14.0)), 0.68, 1.5);
  vec3 bright = fx_tone(fx_hueTurn(A, radians(8.0)), 0.97, 1.15);
  lab = mix(B, deep, 0.55);
  for (int i = 0; i < 2; i++) {
    float fi = float(i);
    float f = fx_sweepForm(q + vec2(0.0, 0.55 - 1.1 * fi), t, 1.7 * fi, 0.55 - 0.15 * fi);
    float inside = smoothstep(-0.02 / sh, 0.05 / sh, f);
    lab = mix(lab, deep, (1.0 - inside) * exp(-max(-f, 0.0) * 5.0) * 0.6);
    lab = mix(lab, mix(deep, bright, exp(-max(f, 0.0) * 2.6)), inside * (0.75 - 0.2 * fi));
  }
  return mix(B, lab, fx_falloff(uv));
}

// FOLD: light panes stacked along slowly bending creases, each a soft body
// behind the crease and a sharp lit rim on it.
vec3 fx_fold(vec2 uv, float t, float dk, vec3 B, vec3 A) {
  vec2 q = fx_frame(uv) * 2.4;
  float px = 2.4 / (2.0 * u_box.x * u_dpr * max(u_scale, 0.05));  // one device pixel in q units
  vec3 Ac = vec3(A.x, A.yz * u_chroma);
  // A small drift only: a wide turn sends a pale-yellow brand's folds to green.
  vec3 A2 = fx_hueTurn(Ac, radians(-20.0)); A2.x = mix(B.x, A.x, 0.85);
  float rimK = 70.0 * fx_sharp();
  vec3 lab = B;
  for (int i = 0; i < 5; i++) {
    float fi = float(i);
    float crease = (fi - 2.0) * 0.34
                 + 0.24 * sin(q.x * (1.0 + 0.14 * fi) + 1.9 * fi + t * (0.3 + 0.06 * fi))
                 + 0.06 * sin(q.x * 2.3 - 0.7 * fi - 0.5 * t);
    float sd = q.y - crease;
    float pane = smoothstep(-px, px, sd);
    float back = max(sd, 0.0);
    float body = exp(-back * 2.4);
    float rim = exp(-back * rimK);
    vec3 tint = mix(mix(B, Ac, 0.55), mix(Ac, A2, 0.5 + 0.5 * sin(2.1 * fi + 0.8 * q.x)), body);
    lab = mix(lab, tint, pane * (0.42 * body + 0.55 * rim));
  }
  return lab;
}

// RISE: a horizon. A bright rim along a gently moving arc low in the frame,
// a wide glow above it fading into the ground, and the body below falling
// from the glow into a deep tone. One focal edge.
vec3 fx_rise(vec2 uv, float t, float dk, vec3 B, vec3 A) {
  float k = fx_aspect();
  vec2 p = fx_frame(uv);
  float px = 1.0 / (2.0 * u_box.x * u_dpr * max(u_scale, 0.05));
  vec3 deep = fx_tone(fx_hueTurn(A, radians(14.0)), mix(0.62, 0.34, dk), 1.6);
  vec3 glow = fx_tone(A, mix(0.86, 0.74, dk), 1.3);
  vec3 rim = fx_tone(fx_hueTurn(A, radians(-10.0)), 0.97, 0.9);
  float x = p.x;
  float edge = -0.20 * k - 0.55 * x * x + 0.025 * sin(3.1 * x + 0.5 * t) + 0.012 * sin(6.0 * x - 0.4 * t);
  float sd = p.y - edge;                       // > 0 above the horizon
  float above = smoothstep(-px, px, sd);
  float halo = exp(-max(sd, 0.0) / (0.22 * k));
  float core = exp(-abs(sd) * fx_sharp() / 0.010);
  vec3 sky = mix(B, deep, halo * 0.55);
  sky = mix(sky, glow, halo * halo * 0.75);
  vec3 body = mix(glow, deep, smoothstep(0.0, 0.22 * k, -sd));
  return mix(mix(body, sky, above), rim, core * 0.9);
}

// DAWN: a soft horizon — light rising from below the frame, with no rim.
// One smooth field of light (a wide hill and a hot core inside it, with
// calm, slowly moving tops) mapped through a colour ramp whose chroma PEAKS
// near the top of the ramp: the colour is strongest where the core meets the
// halo, as in a real glow, and not spread as flat layers. Sharpness sets how
// long the hills' shoulders are.
float fx_hill(float h, float top, float soft) {
  float g = clamp((top + soft - h) / (1.6 * soft), 0.0, 1.0);
  return g * g * g * (g * (g * 6.0 - 15.0) + 10.0);  // smootherstep: no visible knee
}
vec3 fx_dawn(vec2 uv, float t, float dk, vec3 B, vec3 A) {
  float k = fx_aspect();
  vec2 p = fx_frame(uv);
  float h = p.y + 0.5 * k;                      // 0 at the bottom of the frame
  float x = p.x;
  float sh = fx_sharp();
  float wide = 0.46 * k - 0.08 * x * x + 0.018 * sin(2.1 * x + 0.40 * t + 0.7) + 0.008 * sin(4.6 * x - 0.30 * t);
  float hot = 0.24 * k - 0.06 * x * x + 0.014 * sin(1.7 * x - 0.35 * t + 2.2) + 0.006 * sin(4.0 * x + 0.25 * t + 1.0);
  float e = 0.55 * fx_hill(h, wide, 0.36 * k / sh) + 0.45 * fx_hill(h, hot, 0.14 * k / sh);
  float dir = fx_shadowTurn(A);
  // The ramp, from the sky (e = 0) to the heart of the light (e = 1).
  // Dark: base, a deep saturated halo, the accent at full chroma, near white.
  // Light: base, a pale tint, the accent at full chroma, a lighter tint — on
  // a white page the light is colour at its edge, not brightness.
  vec3 halo = fx_tone(fx_hueTurn(A, radians(16.0 * dir)), mix(0.88, 0.40, dk), mix(0.9, 1.6, dk));
  vec3 vivid = fx_tone(fx_hueTurn(A, radians(-6.0 * dir)), mix(0.74, 0.80, dk), 1.55);
  vec3 heart = fx_tone(fx_hueTurn(A, radians(-10.0 * dir)), mix(0.94, 0.98, dk), mix(0.6, 0.28, dk));
  vec3 lab = mix(B, halo, smoothstep(0.0, 0.42, e));
  lab = mix(lab, vivid, smoothstep(0.34, 0.74, e));
  lab = mix(lab, heart, smoothstep(0.72, 1.0, e));
  return lab;
}

void main() {
  vec2 local = fx_local();
  vec2 uv = local / (2.0 * u_box.x);
  float t = u_time * 0.1, dk = fx_isDark();
  vec3 B = fx_oklab(u_base), A = fx_oklab(u_light);
  vec3 lab = u_look < 0.5 ? fx_wash(uv, t, dk, B, A)
           : u_look < 1.5 ? fx_sweep(uv, t, dk, B, A)
           : u_look < 2.5 ? fx_fold(uv, 1.2 * t, dk, B, A)
           : u_look < 3.5 ? fx_rise(uv, t, dk, B, A)
           : fx_dawn(uv, t, dk, B, A);
  // Back to the base wherever the light must not be (the quiet zone, a
  // dissolving edge, a lower intensity); then grain outside the zone only,
  // so the copy's ground stays exact; then the dither, last.
  float keep = fx_quietMask(uv) * fx_edgeMask(local);
  lab = mix(B, mix(B, lab, u_intensity), keep);
  vec3 rgb = fx_srgb(lab);
  // Grain is part of the field: at intensity 0 the ground is the base alone.
  rgb += (fx_rand(uvec3(uvec2(gl_FragCoord.xy), 7u)) - 0.5) * u_grain * keep * u_intensity;
  rgb += fx_tpdf(gl_FragCoord.xy) / 255.0;
  float a = fx_cover(fx_shapeDistance(gl_FragCoord.xy / u_dpr));
  fragColor = vec4(clamp(rgb, 0.0, 1.0) * a, a);
}
`;

export const SHADERS: Record<ShaderName, ShaderDef> = {
  gradient: {
    name: "gradient",
    restTime: 6,
    adaptive: false,
    fps: 30,
    uniforms: {
      // Fallback tokens, not defaults declared on .fx-gradient: a wrapper or
      // a brand scope that sets the gradient's colours must reach it.
      u_base: { color: "--ui-fx-gradient-base", fallback: "--ui-bg-base" },
      u_light: { color: "--ui-fx-gradient-light", fallback: "--ui-bg-accent" },
      u_look: { keyword: "--ui-fx-gradient-look", values: GRADIENT_LOOKS },
      u_angle: { number: "--ui-fx-gradient-angle", fallback: NaN },
      u_sharpness: { number: "--ui-fx-gradient-sharpness", fallback: 0.5 },
      u_scale: { number: "--ui-fx-gradient-scale", fallback: 1 },
      u_chroma: { number: "--ui-fx-gradient-chroma", fallback: 1 },
      u_intensity: { number: "--ui-fx-gradient-intensity", fallback: NaN },
      u_quiet: { number: "--ui-fx-gradient-quiet", fallback: NaN },
      u_quietX: { number: "--ui-fx-gradient-quiet-x", fallback: 0.16 },
      u_quietY: { number: "--ui-fx-gradient-quiet-y", fallback: NaN },
      u_dissolve: { number: "--ui-fx-gradient-dissolve", fallback: 0 },
      u_grain: { number: "--ui-fx-grain-amount", fallback: 0 },
    },
    resolve: (v) => {
      const preset = GRADIENT_PRESETS[GRADIENT_LOOKS[v.u_look as number] ?? "wash"];
      if (Number.isNaN(v.u_angle)) v.u_angle = preset.angle;
      if (Number.isNaN(v.u_intensity)) v.u_intensity = preset.intensity;
      if (Number.isNaN(v.u_quiet)) v.u_quiet = preset.quiet;
      if (Number.isNaN(v.u_quietY)) v.u_quietY = preset.quietY;
      // Every knob within the range its GLSL is written for. Past it the
      // maths breaks, not just the look: sharpness 80 overflows exp2 to
      // infinity and fold's rim turns to NaN; sharpness far below 0 makes
      // dawn divide 0 by 0; intensity past 1 extrapolates in OKLab.
      const clamp = (k: string, lo: number, hi: number) => {
        v[k] = Math.min(hi, Math.max(lo, v[k] as number));
      };
      clamp("u_sharpness", 0, 1);
      clamp("u_scale", 0.25, 4);
      clamp("u_chroma", 0, 2);
      clamp("u_intensity", 0, 1);
      clamp("u_quiet", 0, 1);
      clamp("u_quietX", 0, 1);
      clamp("u_quietY", 0, 1);
      clamp("u_dissolve", 0, 0.5);
      clamp("u_grain", 0, 0.25);
    },
    fragment: GRADIENT,
  },

  halo: {
    name: "halo",
    restTime: 2.2,
    bleed: 22,
    uniforms: {
      u_light: { color: "--ui-fx-halo-light" },
      u_ground: { color: "--ui-bg-base" },
      u_strength: { number: "--ui-fx-halo-strength", fallback: 0, live: true },
      u_loop: { number: "--ui-duration-loop", fallback: 2 },
    },
    idle: (v) => (v.u_strength as number) <= 0.001,
    fragment: `
uniform vec3 u_light;
uniform vec3 u_ground;
uniform float u_strength;  // 0..1, follows a CSS transition
uniform float u_loop;      // --ui-duration-loop, seconds: the light laps once per loop
uniform float u_bleed;
void main() {
  vec2 p = gl_FragCoord.xy / u_dpr - u_center;
  float d = fx_shapeDistance(gl_FragCoord.xy / u_dpr);
  float angle = atan(p.y * (u_box.x / max(u_box.y, 1.0)), p.x);
  vec2 ring = vec2(cos(angle), sin(angle));     // seamless round the edge
  float t = u_time * 0.35;
  float flow = fx_noise(ring * 1.8 + vec2(t, -0.7 * t), 21u) * 0.9 + 0.5;
  // One lap per --ui-duration-loop: a working button and its shimmering
  // status line keep one rhythm.
  float comet = pow(0.5 + 0.5 * cos(angle - u_time * 6.2831853 / max(u_loop, 0.1)), 10.0);
  float energy = clamp(0.3 + flow * 0.6 + comet * 0.9, 0.0, 1.6);
  float outside = max(d, 0.0);
  // No crisp edge line: a sharp ring would read as the focus indicator.
  float glow = exp(-outside / (0.26 * u_bleed));
  float alpha = 0.5 * glow * energy * u_strength * smoothstep(-1.0, 1.0, d);
  vec3 light = fx_oklab(u_light);
  // A small drift only: a wide hue turn sends a green brand's halo to yellow.
  vec3 lab = mix(light, fx_hueTurn(light, radians(-18.0)), 0.5 + 0.5 * sin(angle + t));
  lab.x += fx_oklab(u_ground).x > 0.6 ? -0.06 * comet : 0.05 * comet;
  // A long, faint falloff is a slow ramp too: dither its alpha, last.
  float a = clamp(alpha + step(0.002, alpha) * fx_tpdf(gl_FragCoord.xy) / 255.0, 0.0, 1.0);
  fragColor = vec4(fx_srgb(lab) * a, a);
}`,
  },
};

/*
 * The shader effects' CSS (ADR 0022, 0025) — what the gradient ground and
 * halo are made of, and how their canvases sit and change state. Import
 * after fx/fx.css; the runtime is `startShaders()` from `@/lib/shader`.
 *
 * WHEN a halo is lit is CSS's business, not the runtime's:
 * `--ui-fx-halo-strength` is a registered property the canvas inherits and
 * EASES with the component's own motion tokens, and the runtime reads it only
 * while it transitions. So a busy Button's halo comes in on
 * `--ui-duration-enter` without either knowing about the other.
 */

@property --ui-fx-halo-strength { syntax: "<number>"; inherits: true; initial-value: 0; }

@layer fx {
  /* ------------------------------------------------------------ canvases */

  /* UNDER (default): above the mount's own background, below its content —
     the runtime makes the mount a stacking context for this. OVER: a sibling
     placed directly after a fill inside a track, so later siblings (a
     Slider's thumb) still paint above it.
     Hidden until the first frame: the part's own fill is the floor. The
     shader draws the part's rounded shape itself, so nothing here clips the
     canvas — iOS Safari drops a CSS clip on a canvas while its layer
     animates, which showed as square corners in every transition. */
  .ui-fx-canvas {
    position: absolute;
    display: block;
    pointer-events: none;
    z-index: -1;
    opacity: 0;
    /* Timing by USAGE (transitions.dev polish rules, mapped onto tokens):
       - the reveal over the floor is a content reveal: enter on smooth-out,
         which is exactly --ui-ease-spring;
       - a halo going out is a close: faster and quieter than coming in. */
    transition:
      opacity var(--ui-duration-enter) var(--ui-ease-spring),
      --ui-fx-halo-strength var(--ui-duration-base) var(--ui-ease-out);
  }
  .ui-fx-canvas-over {
    z-index: auto;
  }
  /* Forced colours: the system draws the UI; no canvas at all. */
  @media (forced-colors: active) {
    .ui-fx-canvas {
      display: none;
    }
  }
  :is([data-fx-gradient="live"], [data-fx-gradient="still"]) .ui-fx-canvas-gradient,
  :is([data-fx-halo="live"], [data-fx-halo="still"]) .ui-fx-canvas-halo {
    opacity: 1;
  }

  /* ------------------------------------------------------------ gradient */

  /* A ground is an unslotted surface: a hero band, an empty state, the page
     behind glass. ONE effect, parametric: the look picks the form, every
     other knob is shared. Four knobs follow the look when left at `auto`
     (angle, intensity, the quiet zone's size and height: GRADIENT_PRESETS
     in shader-programs.ts) — so `--ui-fx-gradient-look: rise` alone is a
     finished horizon. The rest have one default for every look.

     The knobs' defaults are declared ON :root and INHERITED, not on
     .fx-gradient: set any of them on the ground, a wrapper or a brand
     scope and it reaches the ground. The two colours are not declared at
     all — they fall back to --ui-bg-base and --ui-bg-accent where the
     ground sits, so a brand scope's accent is the light without a word.

     Its copy sits in the QUIET ZONE — an ellipse around (quiet-x, quiet-y),
     measured from the top left like CSS, whose core is exactly the base.
     Move the zone to where the copy is; 0 turns it off for a ground that
     carries no text (or whose text sits on glass).

     THE FLOOR is a still, faint two-stop version of the light, drawn in CSS:
     what shows before hydration, without WebGL and while the canvas fades
     in. Its light sits in the top-right corner, away from either default
     quiet zone's copy. */
  :root {
    --ui-fx-gradient-look: wash; /* wash · sweep · fold · rise · dawn */
    --ui-fx-gradient-angle: auto; /* deg (or turn, rad): the direction the forms run */
    --ui-fx-gradient-sharpness: 0.5; /* 0 soft … 1 crisp edges and rims */
    --ui-fx-gradient-scale: 1; /* the forms' size, 0.25 … 4 */
    --ui-fx-gradient-chroma: 1; /* colourfulness, 0 … 2: 0.6 quiet, 1.4 vivid */
    --ui-fx-gradient-intensity: auto; /* 0 = the base alone … 1 */
    --ui-fx-gradient-quiet: auto; /* 0.42; 0.3 for the horizons; 0 = none */
    --ui-fx-gradient-quiet-x: 0.16; /* 0 … 1, or a percentage */
    --ui-fx-gradient-quiet-y: auto;
    --ui-fx-gradient-dissolve: 0; /* 0 … 0.5 */
  }
  .fx-gradient {
    --ui-fx-gradient-floor-base: var(--ui-fx-gradient-base, var(--ui-bg-base));
    --ui-fx-gradient-floor-light: var(--ui-fx-gradient-light, var(--ui-bg-accent));
    background-color: var(--ui-fx-gradient-floor-base);
    background-image: radial-gradient(
      in oklab ellipse 70% 80% at 92% 6%,
      color-mix(in oklab, var(--ui-fx-gradient-floor-light) 30%, var(--ui-fx-gradient-floor-base)),
      var(--ui-fx-gradient-floor-base) 72%
    );

    @media (forced-colors: active) {
      background-image: none;
    }
  }

  /* ---------------------------------------------------------------- halo */

  /* Lit while the surface works (aria-busy) or listens (focus within a
     field). `data-fx-active` lights it by hand — a field listening for voice
     — and is searched INSIDE too, because a form control sends native props
     to its <input>, not to the root that carries the class. */
  .fx-halo {
    --ui-fx-halo-light: var(--ui-border-focus);
    --ui-fx-halo-strength: 0;
  }
  .fx-halo:is([aria-busy="true"], [data-fx-active], :has([data-fx-active])),
  .fx-halo[data-slot="field"]:focus-within {
    --ui-fx-halo-strength: 1;
  }
  /* In while work starts: an emphasis open, enter on smooth-out. On a field
     it comes in on focus — every Tab press — so quicker, and its exit is
     quicker still. Never delay an exit. */
  .fx-halo:is([aria-busy="true"], [data-fx-active], :has([data-fx-active])) .ui-fx-canvas-halo {
    transition:
      opacity var(--ui-duration-enter) var(--ui-ease-spring),
      --ui-fx-halo-strength var(--ui-duration-enter) var(--ui-ease-spring);
  }
  .fx-halo[data-slot="field"] .ui-fx-canvas-halo {
    transition:
      opacity var(--ui-duration-enter) var(--ui-ease-spring),
      --ui-fx-halo-strength var(--ui-duration-fast) var(--ui-ease-out);
  }
  .fx-halo[data-slot="field"]:focus-within .ui-fx-canvas-halo {
    transition:
      opacity var(--ui-duration-enter) var(--ui-ease-spring),
      --ui-fx-halo-strength var(--ui-duration-base) var(--ui-ease-spring);
  }
  /* The floor where the shader is not drawing: a still, soft glow. Never a
     crisp ring, which would read as the focus indicator. */
  .fx-halo[data-slot="button"]:is([aria-busy="true"], [data-fx-active]):not([data-fx-halo="live"], [data-fx-halo="still"]) {
    --tw-shadow: 0 0 18px -2px color-mix(in oklab, var(--ui-fx-halo-light) 42%, transparent);

    /* Nested, so it carries this rule's specificity (see fx/base.css). */
    @media (forced-colors: active) {
      --tw-shadow: revert-layer;
    }
  }
}
